patch:
diff --git a/recreate-no-var-tdz.js b/recreate-no-var-tdz.js
new file mode 100644
index 0000000..1af4175
--- /dev/null
+++ b/recreate-no-var-tdz.js
@@ -0,0 +1,71 @@
+/**
+ * Check for the reported bug: `no-var` autofix turns
+ *
+ *     export function a() { console.log(o); var o; return o; }
+ *
+ * into `let o` placed after `console.log(o)`, which throws a ReferenceError
+ * (temporal dead zone) where the original code ran fine.
+ *
+ * Exits 1 while the bug is present, 0 when it is not.
+ *
+ * Usage (from the repo root):
+ *     node recreate-no-var-tdz.js
+ * To try another ESLint install, e.g. the reporter's version:
+ *     ESLINT_PATH=/path/to/node_modules/eslint node recreate-no-var-tdz.js
+ */
+"use strict";
+
+const vm = require("node:vm");
+const path = require("node:path");
+
+const { Linter } = require(
+	process.env.ESLINT_PATH
+		? path.resolve(process.env.ESLINT_PATH)
+		: "./lib/api",
+);
+
+const code = `export function a() {
+    console.log(o);
+    var o;
+    return o;
+}
+`;
+
+// Same config as the report: only `no-var` as an error, default (Espree) parser.
+const config = [{ rules: { "no-var": ["error"] } }];
+
+/**
+ * Runs the (module-less) function `a` and reports whether it throws.
+ * @param {string} source The source text containing `export function a`.
+ * @returns {string} "ok" or the name of the error thrown when calling `a()`.
+ */
+function run(source) {
+	const sandbox = { console: { log() {} } };
+
+	try {
+		vm.runInNewContext(
+			`${source.replace(/^export /mu, "")}\na();`,
+			sandbox,
+		);
+	} catch (error) {
+		return error.name;
+	}
+	return "ok";
+}
+
+const linter = new Linter();
+const { output, fixed } = linter.verifyAndFix(code, config);
+const before = run(code);
+const after = run(output);
+
+console.log(`ESLint ${Linter.version}`);
+console.log(`fix applied: ${fixed}`);
+console.log(`--- output ---\n${output}--------------`);
+console.log(`running original: ${before}; running fixed output: ${after}`);
+
+if (before === "ok" && after !== "ok") {
+	console.error(`BUG PRESENT: the no-var fix introduced a ${after}`);
+	process.exitCode = 1;
+} else {
+	console.log("OK: the no-var fix did not change the behavior");
+}
